import { getPermissions } from "@/common/Permissions";

import { usePermissions } from "@/context/PermissionContext";

import { useCurrentFacilitySilently } from "@/pages/Facility/utils/useCurrentFacility";

import { ValueSetScope } from "@/types/valueSet/valueSet";

/**
 * Whether the current user may create or edit value sets in `scope` — the
 * single gate for the list's Create button, the editor's save and the
 * departments field.
 *
 * Facility mounts gate on the facility's *object* permissions (the backend
 * checks `can_write_valueset` in the facility's root organization); the
 * admin mount falls back to the user's own permission union, since no
 * object-scoped permissions apply to an instance-wide list.
 *
 * `isLoading` is true while the facility (and its permissions) is still
 * being fetched on a facility mount, so callers can hold a skeleton instead
 * of flashing a denied state.
 */
export function useCanWriteValueSet(scope: ValueSetScope): {
  canWrite: boolean;
  isLoading: boolean;
} {
  const { hasPermission, userPermissions } = usePermissions();
  const { facility, isFacilityLoading } = useCurrentFacilitySilently();

  const { canWriteValueSet } = getPermissions(
    hasPermission,
    scope.authContext === "facility"
      ? (facility?.permissions ?? [])
      : userPermissions,
  );

  return {
    canWrite: canWriteValueSet,
    // Track the fetch, not data presence — a user who cannot read the
    // facility (404) would otherwise leave `!facility` true forever.
    isLoading: scope.authContext === "facility" && isFacilityLoading,
  };
}
import { CaretSortIcon } from "@radix-ui/react-icons";
import React, { useEffect, useRef, useState } from "react";

import { cn } from "@/lib/utils";

import { Button } from "@/components/ui/button";
import {
  Drawer,
  DrawerContent,
  DrawerTitle,
  DrawerTrigger,
} from "@/components/ui/drawer";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";

import { ValueSetPickerSearch } from "@/components/Questionnaire/ValueSetPickerSearch";

import useBreakpoints from "@/hooks/useBreakpoints";

import { Code } from "@/types/base/code/code";
import { useTranslation } from "react-i18next";

type ButtonProps = Omit<React.ComponentProps<typeof Button>, keyof Props>;

interface Props {
  system: string;
  /** Pins the lookup to one exact valueset, bypassing slug resolution. */
  valuesetId?: string;
  value?: Code | null;
  onSelect: (value: Code) => void;
  placeholder?: string;
  count?: number;
  searchPostFix?: string;
  hideTrigger?: boolean;
  controlledOpen?: boolean;
  showCode?: boolean;
  title?: string;
  closeOnSelect?: boolean;
  mobileTrigger?: React.ReactNode;
}

export default function ValueSetSelect({
  system,
  valuesetId,
  value,
  onSelect,
  placeholder = "Search...",
  count = 10,
  searchPostFix = "",
  hideTrigger = false,
  controlledOpen = false,
  closeOnSelect = true,
  showCode = false,
  title,
  mobileTrigger,
  ...props
}: Props & ButtonProps) {
  const { t } = useTranslation();
  const [internalOpen, setInternalOpen] = useState(false);
  const isMobile = useBreakpoints({ default: true, sm: false });
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (internalOpen && isMobile) {
      const timer = setTimeout(() => {
        inputRef.current?.focus();
      }, 200);
      return () => clearTimeout(timer);
    }
  }, [internalOpen, isMobile]);
  const searchContent = (
    <ValueSetPickerSearch
      key={`${controlledOpen}-${internalOpen}`}
      inputRef={inputRef}
      system={system}
      valuesetId={valuesetId}
      onSelect={(selected) => {
        onSelect(selected);
        if (closeOnSelect) {
          setInternalOpen(false);
        } else {
          inputRef.current?.focus();
        }
      }}
      placeholder={placeholder}
      count={count}
      searchPostFix={searchPostFix}
      showCode={showCode}
      title={title}
    />
  );

  if (isMobile && !hideTrigger) {
    return (
      <Drawer
        open={internalOpen || controlledOpen}
        onOpenChange={setInternalOpen}
      >
        <DrawerTrigger asChild>
          {mobileTrigger ? (
            mobileTrigger
          ) : (
            <Button
              variant="white"
              role="combobox"
              className={cn(
                "w-full flex justify-between h-auto whitespace-normal text-left font-normal border-gray-300 shadow-xs",
                !value?.display && "text-gray-500 hover:bg-white",
              )}
              {...props}
            >
              <span>
                {value?.display || placeholder}
                {value?.display && showCode && (
                  <span className="text-xs ml-1">({value?.code})</span>
                )}
              </span>
              <CaretSortIcon className="ml-2 size-4 shrink-0 opacity-50" />
            </Button>
          )}
        </DrawerTrigger>
        <DrawerContent>
          <DrawerTitle className="sr-only">
            {title || t("select_value")}
          </DrawerTitle>
          {searchContent}
        </DrawerContent>
      </Drawer>
    );
  }

  if (hideTrigger) {
