import { HttpMethod, PaginatedResponse, Type } from "@/Utils/request/types";
import {
  ImmunizationPolicyCreate,
  ImmunizationPolicyRead,
  ImmunizationPolicyWrite,
} from "@/types/emr/immunizationPolicy/immunizationPolicy";

export default {
  list: {
    path: "/api/v1/immunization/policy/",
    method: HttpMethod.GET,
    TRes: Type<PaginatedResponse<ImmunizationPolicyRead>>(),
  },
  retrieve: {
    path: "/api/v1/immunization/policy/{id}/",
    method: HttpMethod.GET,
    TRes: Type<ImmunizationPolicyRead>(),
  },
  create: {
    path: "/api/v1/immunization/policy/",
    method: HttpMethod.POST,
    TBody: Type<ImmunizationPolicyCreate>(),
    TRes: Type<ImmunizationPolicyRead>(),
  },
  update: {
    path: "/api/v1/immunization/policy/{id}/",
    method: HttpMethod.PUT,
    TBody: Type<ImmunizationPolicyWrite>(),
    TRes: Type<ImmunizationPolicyRead>(),
  },
} as const;

import { Code } from "@/types/base/code/code";

export const IMMUNIZATION_FORECAST_STATUSES = [
  "due",
  "immune",
  "contraindicated",
  "complete",
] as const;

export interface ImmunizationPolicyTemplate {
  id?: string | null;
  codes: Code[];
  diseases?: Code[];
  forecast_status: (typeof IMMUNIZATION_FORECAST_STATUSES)[number];
  is_group: boolean;
  children: ImmunizationPolicyTemplate[];
  description?: string;
  series?: string;
  dose_number?: string;
  series_number?: string;
  // The policy API accepts integer offsets, rather than patient dates.
  earliest_date?: number;
  due_date?: number;
  overdue_date?: number;
}

export interface ImmunizationPolicyWrite {
  name: string;
  description?: string;
  policy_template: ImmunizationPolicyTemplate;
}

export interface ImmunizationPolicyCreate extends ImmunizationPolicyWrite {
  facility: string | null;
}

export interface ImmunizationPolicyRead extends ImmunizationPolicyWrite {
  id: string;
  // Older versions of the policy API omit ownership from read responses.
  facility?: string | null;
}

export interface ImmunizationPolicyScope {
  basePath: string;
  facilityId?: string;
}

export function immunizationPolicyScope(facilityId?: string): ImmunizationPolicyScope {
  return {
    facilityId,
    basePath: facilityId
      ? `/facility/${facilityId}/settings/immunization-policies`
      : "/admin/immunization-policies",
  };
}

