import * as LabelPrimitive from "@radix-ui/react-label";
import { Slot } from "@radix-ui/react-slot";
import * as React from "react";
import {
  Controller,
  type ControllerProps,
  type FieldPath,
  type FieldValues,
  FormProvider,
  useFormContext,
  useFormState,
} from "react-hook-form";

import { cn } from "@/lib/utils";

import { Label } from "@/components/ui/label";

const Form = FormProvider;

type FormFieldContextValue<
  TFieldValues extends FieldValues = FieldValues,
  TName extends FieldPath<TFieldValues> = FieldPath<TFieldValues>,
> = {
  name: TName;
};

const FormFieldContext = React.createContext<FormFieldContextValue>(
  {} as FormFieldContextValue,
);

const FormField = <
  TFieldValues extends FieldValues = FieldValues,
  TName extends FieldPath<TFieldValues> = FieldPath<TFieldValues>,
>({
  ...props
}: ControllerProps<TFieldValues, TName>) => {
  return (
    <FormFieldContext.Provider value={{ name: props.name }}>
      <Controller {...props} />
    </FormFieldContext.Provider>
  );
};

const useFormField = () => {
  const fieldContext = React.useContext(FormFieldContext);
  const itemContext = React.useContext(FormItemContext);
  const { getFieldState } = useFormContext();
  const formState = useFormState({ name: fieldContext.name });
  const fieldState = getFieldState(fieldContext.name, formState);

  if (!fieldContext) {
    throw new Error("useFormField should be used within <FormField>");
  }

  const { id } = itemContext;

  return {
    id,
    name: fieldContext.name,
    formItemId: `${id}-form-item`,
    formDescriptionId: `${id}-form-item-description`,
    formMessageId: `${id}-form-item-message`,
    ...fieldState,
  };
};

type FormItemContextValue = {
  id: string;
};

const FormItemContext = React.createContext<FormItemContextValue>(
  {} as FormItemContextValue,
);

function FormItem({ className, ...props }: React.ComponentProps<"div">) {
  const id = React.useId();

  return (
    <FormItemContext.Provider value={{ id }}>
      <div
        data-slot="form-item"
        className={cn("grid gap-2", className)}
        {...props}
      />
    </FormItemContext.Provider>
  );
}

function FormLabel({
  className,
  ...props
}: React.ComponentProps<typeof LabelPrimitive.Root>) {
  const { error, formItemId } = useFormField();

  return (
    <Label
      data-slot="form-label"
      data-error={!!error}
      className={cn(
        "data-[error=true]:text-red-500 dark:data-[error=true]:text-red-900",
        className,
      )}
      htmlFor={formItemId}
      {...props}
    />
  );
}

function FormControl({ ...props }: React.ComponentProps<typeof Slot>) {
  const { error, formItemId, formDescriptionId, formMessageId } =
    useFormField();

  return (
    <Slot
      data-slot="form-control"
      id={formItemId}
      aria-describedby={
        !error
          ? `${formDescriptionId}`
          : `${formDescriptionId} ${formMessageId}`
      }
      aria-invalid={!!error}
      {...props}
    />
  );
}

function FormDescription({ className, ...props }: React.ComponentProps<"p">) {
  const { formDescriptionId } = useFormField();

  return (
    <p
      data-slot="form-description"
      id={formDescriptionId}
      className={cn("text-gray-500 text-sm dark:text-gray-400", className)}
      {...props}
    />
  );
}

function FormMessage({ className, ...props }: React.ComponentProps<"p">) {
  const { error, formMessageId } = useFormField();
  const body = error ? String(error?.message ?? "") : props.children;

  if (!body) {
    return null;
  }

  return (
    <p
      data-slot="form-message"
      id={formMessageId}
      className={cn("text-red-500 text-sm dark:text-red-900", className)}
      {...props}
    >
      {body}
    </p>
  );
}

export {
  Form,
  FormControl,
  FormDescription,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
  useFormField,
};
import { useQuery } from "@tanstack/react-query";
import { useFullPath } from "raviger";

import query from "@/Utils/request/query";
import facilityApi from "@/types/facility/facilityApi";

const extractFacilityId = (path: string) => {
  const segments = path.split("/");

  if (segments[1] === "facility" && segments[2]) {
    return segments[2];
  }

  return undefined;
};

/**
 * Avoids fetching the facility data on all places the current facility is needed.
 *
 * @returns The current facility in context.
 */
export default function useCurrentFacility() {
  const context = useCurrentFacilitySilently();

  if (!context.facilityId) {
    throw new Error(
      "'useCurrentFacility' must be used within a facility route",
    );
  }

  return { ...context, facilityId: context.facilityId };
}

export function useCurrentFacilitySilently() {
  const path = useFullPath();
  const facilityId = extractFacilityId(path);

  const { data: facility, isLoading: isFacilityLoading } = useQuery({
    queryKey: ["facility", facilityId],
    queryFn: query(facilityApi.get, {
      pathParams: { facilityId: facilityId ?? "" },
    }),
    enabled: !!facilityId,
    staleTime: 1000 * 60 * 5, // cache for 5 minutes
  });

  return { facilityId, facility, isFacilityLoading };
}
import { AlertCircle } from "lucide-react";
import { useFormState, type Control } from "react-hook-form";
import { useTranslation } from "react-i18next";

import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";

import { collectFormIssues, type FormIssue } from "./collectValueSetFormIssues";
import type { ValueSetFormData } from "./valueSetFormTypes";

interface ValueSetFormErrorsProps {
  control: Control<ValueSetFormData>;
  onFocusIssue: (issue: FormIssue) => void;
}

export function ValueSetFormErrors({
  control,
  onFocusIssue,
}: ValueSetFormErrorsProps) {
  const { t } = useTranslation();
  const { errors, submitCount } = useFormState({ control });
  const issues = collectFormIssues(errors);
  const issueLabel = (issue: FormIssue) => {
    const parts = issue.name.split(".");
    if (parts[0] !== "compose") return t(parts[0]);
    const rule = t(
      parts[1] === "include"
        ? "valueset_include_rule"
        : "valueset_exclude_rule",
      { number: Number(parts[2]) + 1 },
    );
    if (parts[3] === "concept" || parts[3] === "filter") {
      const location = t("valueset_issue_location", {
        rule,
        item: t(
          parts[3] === "concept"
            ? "valueset_concept_number"
            : "valueset_filter_number",
          { number: Number(parts[4]) + 1 },
        ),
      });
      const fieldLabel = t(
        parts[5] === "op"
          ? "operator"
          : parts[5] === "display"
            ? "display_name"
            : parts[5],
      );
      return `${location} · ${fieldLabel}`;
    }
    return rule;
  };
  return (
    <>
      {submitCount > 0 && issues.length > 0 && (
        <Alert variant="destructive" className="border-red-200">
          <AlertCircle />
          <AlertTitle>{t("valueset_fix_errors")}</AlertTitle>
          <AlertDescription>
            <ul className="space-y-1">
              {issues.map((issue) => (
                <li key={issue.name}>
                  <button
                    type="button"
                    className="cursor-pointer text-left underline underline-offset-2"
                    onClick={() => onFocusIssue(issue)}
                  >
                    {issueLabel(issue)}: {issue.message}
                  </button>
                </li>
              ))}
            </ul>
          </AlertDescription>
        </Alert>
      )}
    </>
  );
}
import { useState, type ComponentProps } from "react";

import ValueSetSearchContent from "@/components/Questionnaire/ValueSetSearchContent";

type ValueSetPickerSearchProps = Omit<
  ComponentProps<typeof ValueSetSearchContent>,
  "search" | "onSearchChange"
>;

/** A picker opening owns a fresh search; closing it discards that search. */
export function ValueSetPickerSearch(props: ValueSetPickerSearchProps) {
  const [search, setSearch] = useState("");
  return (
    <ValueSetSearchContent
      {...props}
      search={search}
      onSearchChange={setSearch}
    />
  );
}
import type { UseFormReturn } from "react-hook-form";
import { useTranslation } from "react-i18next";

import { Button } from "@/components/ui/button";
import {
  FormControl,
  FormDescription,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";

import { ValueSetRead, ValueSetStatus } from "@/types/valueSet/valueSet";

import { generateSlug, valuesOf } from "@/Utils/utils";

import { SLUG_MAX, type ValueSetFormData } from "./valueSetFormTypes";

interface ValueSetBasicFieldsProps {
  form: UseFormReturn<ValueSetFormData>;
  initialData?: ValueSetRead;
  inherited: boolean;
  isSlugManuallyEdited: boolean;
  onSlugManuallyEdited: () => void;
  disabled?: boolean;
  isSharedSlugCheckBlocked: boolean;
  showSharedCatalogueError: boolean;
  onRetrySharedCatalogue: () => void;
}

export function ValueSetBasicFields({
  form,
  initialData,
  inherited,
  isSlugManuallyEdited,
  onSlugManuallyEdited,
  disabled,
  isSharedSlugCheckBlocked,
  showSharedCatalogueError,
  onRetrySharedCatalogue,
}: ValueSetBasicFieldsProps) {
  const { t } = useTranslation();
  return (
    <section className="space-y-4 border-b border-gray-200 pb-6">
      <h2 className="text-base font-semibold tracking-tight text-gray-900">
        {t("basic_information")}
      </h2>
      <div className="grid items-start gap-4 sm:grid-cols-2 lg:grid-cols-[minmax(0,1.2fr)_minmax(0,1fr)_180px]">
        <FormField
          control={form.control}
          name="name"
          render={({ field }) => (
            <FormItem>
              <FormLabel aria-required>{t("name")}</FormLabel>
              <FormControl>
                <Input
                  {...field}
                  disabled={disabled}
                  className="h-12 md:h-10"
                  placeholder={t("valueset_name_placeholder")}
                  onChange={(event) => {
                    field.onChange(event);
                    if (
                      initialData ||
                      form.getValues("inherited") ||
                      isSlugManuallyEdited
                    ) {
                      return;
                    }
                    form.setValue(
                      "slug",
                      generateSlug(event.target.value, SLUG_MAX),
                      {
                        shouldValidate: true,
                        shouldDirty: false,
                      },
                    );
                  }}
                />
              </FormControl>
              <FormMessage />
            </FormItem>
          )}
        />

        <FormField
          control={form.control}
          name="slug"
          render={({ field }) => (
            <FormItem>
              <FormLabel aria-required>{t("slug")}</FormLabel>
              <FormControl>
                {/* Locked on the element, not the Controller: a
                            disabled Controller drops its value from submitted
                            data, but existing and inherited slugs must still
                            reach the backend. */}
                <Input
                  {...field}
                  disabled={disabled || !!initialData || inherited}
                  className="h-12 font-mono text-sm md:h-10"
                  onChange={(event) => {
                    const sanitizedValue = event.target.value
                      .toLowerCase()
                      .replace(/[^a-z0-9_-]/g, "");
                    onSlugManuallyEdited();
                    form.setValue("slug", sanitizedValue, {
                      shouldValidate: true,
                      shouldDirty: true,
                    });
                  }}

