import { TFunction } from "i18next";
import { z } from "zod";

import { CodeSchema } from "@/types/base/code/code";
import {
  IMMUNIZATION_FORECAST_STATUSES,
  ImmunizationPolicyTemplate,
} from "@/types/emr/immunizationPolicy/immunizationPolicy";

export function newPolicyTemplate(isGroup = false): ImmunizationPolicyTemplate {
  return {
    codes: [],
    forecast_status: "due",
    is_group: isGroup,
    children: [],
  };
}

export function policySchema(t: TFunction) {
  const offset = z.number().int(t("immunization_offset_integer")).optional();
  const template: z.ZodType<ImmunizationPolicyTemplate> = z.lazy(() =>
    z.object({
      id: z.string().nullable().optional(),
      codes: z.array(CodeSchema).min(1, t("immunization_codes_required")),
      diseases: z.array(CodeSchema).optional(),
      forecast_status: z.enum(IMMUNIZATION_FORECAST_STATUSES),
      is_group: z.boolean(),
      children: z.array(template),
      description: z.string().optional(),
      series: z.string().max(255).optional(),
      dose_number: z.string().max(255).optional(),
      series_number: z.string().max(255).optional(),
      earliest_date: offset,
      due_date: offset,
      overdue_date: offset,
    }).superRefine((node, context) => {
      if (!node.is_group && node.children.length > 0) {
        context.addIssue({
          code: "custom",
          path: ["is_group"],
          message: t("immunization_only_groups_have_children"),
        });
      }
      const dates = ["earliest_date", "due_date", "overdue_date"] as const;
      let previous: number | undefined;
      for (const field of dates) {
        const value = node[field];
        if (value === undefined) continue;
        if (previous !== undefined && previous >= value) {
          context.addIssue({
            code: "custom",
            path: [field],
            message: t("immunization_offsets_order"),
          });
        }
        previous = value;
      }
    }),
  );

  return z.object({
    name: z.string().trim().min(1, t("field_required")).max(255),
    description: z.string(),
    policy_template: template,
  });
}

/** Optional database fields may arrive as null; optional writes use omission. */
export function normalizePolicyTemplate(
  template: ImmunizationPolicyTemplate,
): ImmunizationPolicyTemplate {
  return {
    ...template,
    children: (template.children ?? []).map(normalizePolicyTemplate),
    diseases: template.diseases ?? [],
    description: template.description ?? "",
    series: template.series ?? "",
    dose_number: template.dose_number ?? "",
    series_number: template.series_number ?? "",
    earliest_date: template.earliest_date ?? undefined,
    due_date: template.due_date ?? undefined,
    overdue_date: template.overdue_date ?? undefined,
  };
}

import { X } from "lucide-react";
import { useId } from "react";
import { useTranslation } from "react-i18next";

import ValueSetSelect from "@/components/Questionnaire/ValueSetSelect";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";

import { Code } from "@/types/base/code/code";

interface PolicyCodePickerProps {
  codes: Code[];
  onChange: (codes: Code[]) => void;
  kind: "vaccine" | "disease";
  disabled: boolean;
  error?: string;
}

export function PolicyCodePicker({
  codes,
  onChange,
  kind,
  disabled,
  error,
}: PolicyCodePickerProps) {
  const { t } = useTranslation();
  const id = useId();
  return (
    <div className="space-y-2">
      <Label htmlFor={id}>
        {t(kind === "vaccine" ? "immunization_vaccine_codes" : "immunization_target_diseases")}
        {kind === "vaccine" && <span aria-hidden="true"> *</span>}
      </Label>
      {codes.length > 0 && (
        <ul className="flex flex-wrap gap-2">
          {codes.map((code) => (
            <li key={`${code.system}|${code.code}`} className="inline-flex max-w-full items-center gap-1 rounded-md border border-gray-200 bg-gray-50 py-1 pl-2 pr-1 text-sm">
              <span className="min-w-0 break-words" title={`${code.system} | ${code.code}`}>{code.display || code.code}</span>
              {!disabled && (
                <Button
                  type="button"
                  variant="ghost"
                  size="icon"
                  className="size-6 shrink-0"
                  aria-label={t("immunization_remove_code", { name: code.display || code.code })}
                  onClick={() => onChange(codes.filter((entry) => entry.system !== code.system || entry.code !== code.code))}
                >
                  <X className="size-3" aria-hidden="true" />
                </Button>
              )}
            </li>
          ))}
        </ul>
      )}
      <ValueSetSelect
        id={id}
        system={kind === "vaccine" ? "system-medication" : "system-condition-code"}
        placeholder={t(kind === "vaccine" ? "immunization_add_vaccine" : "immunization_add_disease")}
        aria-label={t(kind === "vaccine" ? "immunization_add_vaccine" : "immunization_add_disease")}
        aria-required={kind === "vaccine"}
        aria-invalid={!!error}
        aria-describedby={error ? `${id}-error` : undefined}
        disabled={disabled}
        className="w-full"
        onSelect={(code) => {
          if (!codes.some((entry) => entry.system === code.system && entry.code === code.code)) onChange([...codes, code]);
        }}
      />
      {error && <p id={`${id}-error`} className="text-sm text-red-600" role="alert">{error}</p>}
    </div>
  );
}

