                  onChange={(event) => onChange({ ...value, [field]: event.target.value === "" ? undefined : Number(event.target.value) })}
                  aria-invalid={!!error}
                  aria-describedby={`${id}-offset-help${error ? ` ${id}-${field}-error` : ""}`}
                />
                {error && <p id={`${id}-${field}-error`} className="text-sm text-red-600" role="alert">{error}</p>}
              </div>
            );
          })}
        </div>
      </div>

      {value.is_group && (
        <div className="space-y-4 border-l-2 border-primary-200 pl-3 sm:pl-4">
          {value.children.map((child, index) => (
            <PolicyTemplateEditor
              key={child.id ?? index}
              value={child}
              path={[...path, "children", index]}
              issues={issues}
              disabled={disabled}
              title={t(child.is_group ? "immunization_group_number" : "immunization_recommendation_number", { number: index + 1 })}
              onChange={(updated) => onChange({ ...value, children: value.children.map((entry, childIndex) => childIndex === index ? updated : entry) })}
              onRemove={() => onChange({ ...value, children: value.children.filter((_, childIndex) => childIndex !== index) })}
            />
          ))}
          {!disabled && (
            <div className="flex flex-wrap gap-2">
              <Button type="button" variant="outline" size="sm" onClick={() => onChange({ ...value, children: [...value.children, newPolicyTemplate()] })}>
                <Plus className="size-4" aria-hidden="true" />{t("immunization_add_recommendation")}
              </Button>
              <Button type="button" variant="outline" size="sm" onClick={() => onChange({ ...value, children: [...value.children, newPolicyTemplate(true)] })}>
                <Plus className="size-4" aria-hidden="true" />{t("immunization_add_group")}
              </Button>
            </div>
          )}
        </div>
      )}
    </fieldset>
  );
}

