import { useQuery } from "@tanstack/react-query";
import {
  ArrowRight,
  Building2,
  Globe2,
  Plus,
  Search,
  Syringe,
} from "lucide-react";
import { Link } from "raviger";
import { useId } from "react";
import { useTranslation } from "react-i18next";

import PageHeadTitle from "@/components/Common/PageHeadTitle";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Skeleton } from "@/components/ui/skeleton";

import useFilters from "@/hooks/useFilters";

import query from "@/Utils/request/query";
import {
  ImmunizationPolicyScope,
  ImmunizationPolicyTemplate,
} from "@/types/emr/immunizationPolicy/immunizationPolicy";
import immunizationPolicyApi from "@/types/emr/immunizationPolicy/immunizationPolicyApi";

import { useImmunizationPolicyAccess } from "./useImmunizationPolicyAccess";

function countRecommendations(template: ImmunizationPolicyTemplate): number {
  return template.is_group
    ? template.children.reduce(
        (count, child) => count + countRecommendations(child),
        0,
      )
    : 1;
}

export default function ImmunizationPolicyList({
  scope,
}: {
  scope: ImmunizationPolicyScope;
}) {
  const { t } = useTranslation();
  const searchId = useId();
  const {
    canRead,
    canWrite,
    isLoading: isAccessLoading,
  } = useImmunizationPolicyAccess(scope);
  const { qParams, updateQuery, Pagination, resultsPerPage } = useFilters({
    limit: 15,
    disableCache: true,
  });
  const { data, isLoading, isError, refetch } = useQuery({
    queryKey: ["immunization-policies", scope.facilityId, qParams],
    queryFn: query.debounced(immunizationPolicyApi.list, {
      queryParams: {
        facility: scope.facilityId,
        name: qParams.name || undefined,
        limit: resultsPerPage,
        offset: ((qParams.page || 1) - 1) * resultsPerPage,
        ordering: "-created_date",
      },
    }),
    enabled: canRead && !isAccessLoading,
  });
  const loading = isAccessLoading || isLoading;
  const policies = data?.results ?? [];

  return (
    <div className="container mx-auto space-y-6 px-4 py-6">
      <PageHeadTitle title={t("immunization_policies")} />
      <div className="flex flex-wrap items-start justify-between gap-4">
        <div className="min-w-0 max-w-2xl space-y-2">
          <div className="flex flex-wrap items-center gap-3">
            <h1 className="text-2xl font-semibold tracking-tight text-gray-950">
              {t("immunization_policies")}
            </h1>
            <Badge variant="outline" size="xs">
              {scope.facilityId ? (
                <Building2 className="size-3" aria-hidden="true" />
              ) : (
                <Globe2 className="size-3" aria-hidden="true" />
              )}
              {t(
                scope.facilityId
                  ? "immunization_scope_facility"
                  : "immunization_scope_instance",
              )}
            </Badge>
          </div>
          <p className="text-sm leading-6 text-gray-600">
            {t(
              scope.facilityId
                ? "immunization_policy_facility_list_hint"
                : "immunization_policy_instance_list_hint",
            )}
          </p>
        </div>
        {canWrite && !isAccessLoading && (
          <Button asChild className="h-10 shrink-0">
            <Link href={`${scope.basePath}/new`} basePath="/">
              <Plus className="size-4" aria-hidden="true" />
              {t("immunization_policy_new")}
            </Link>
          </Button>
        )}
      </div>

      {!isAccessLoading && !canRead ? (
        <Alert>
          <AlertDescription>
            {t("immunization_policy_access_denied")}
          </AlertDescription>
        </Alert>
      ) : (
        <>
          <div className="max-w-md space-y-2">
            <Label htmlFor={searchId}>{t("search")}</Label>
            <div className="relative">
              <Search
                className="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2 text-gray-500"
                aria-hidden="true"
              />
              <Input
                id={searchId}
                value={qParams.name || ""}
                placeholder={t("immunization_policy_search")}
                className="h-10 pl-9"
                onChange={(event) =>
                  updateQuery({ name: event.target.value, page: 1 })
                }
              />
            </div>
          </div>

          {loading ? (
            <div
              className="divide-y rounded-lg border bg-white"
              aria-busy="true"
              aria-label={t("loading")}
            >
              {Array.from({ length: 4 }).map((_, index) => (
                <div key={index} className="space-y-3 p-5">
                  <Skeleton className="h-5 w-1/3" />
                  <Skeleton className="h-4 w-2/3" />
                </div>
              ))}
            </div>
          ) : isError ? (
            <Alert variant="destructive">
              <AlertDescription className="flex flex-wrap items-center justify-between gap-3">
                <span>{t("immunization_policy_list_error")}</span>
                <Button variant="outline" onClick={() => refetch()}>
                  {t("immunization_retry")}
                </Button>
              </AlertDescription>
            </Alert>
          ) : policies.length === 0 ? (
            <div className="flex flex-col items-center rounded-lg border border-dashed bg-white px-6 py-14 text-center">
              <Syringe
                className="mb-4 size-8 text-primary-700"
                aria-hidden="true"
              />
              <h2 className="text-lg font-semibold text-gray-950">
                {t(
                  qParams.name
                    ? "immunization_policy_search_empty"
                    : "immunization_policy_empty",
                )}
              </h2>
              <p className="mt-2 max-w-md text-sm leading-6 text-gray-600">
                {t(
                  qParams.name
                    ? "immunization_policy_search_empty_hint"
                    : "immunization_policy_empty_hint",
                )}
              </p>
              {qParams.name && (
                <Button
                  variant="outline"
                  className="mt-5"
                  onClick={() => updateQuery({ name: undefined, page: 1 })}
                >
                  {t("clear_search")}
                </Button>
              )}
            </div>
          ) : (
            <ul className="divide-y divide-gray-200 overflow-hidden rounded-lg border border-gray-200 bg-white">
              {policies.map((policy) => {
                const ownership =
                  policy.facility === undefined
                    ? "unknown"
                    : policy.facility === null
                      ? "instance"
                      : "facility";
                const editable =
                  canWrite &&
                  policy.facility !== undefined &&
                  policy.facility === (scope.facilityId ?? null);

                return (
                  <li key={policy.id}>
                    <Link
                      href={`${scope.basePath}/${policy.id}`}
                      basePath="/"
                      className="group flex items-center gap-4 px-5 py-5 transition-colors hover:bg-gray-50 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-primary-500"
                    >
                      <div className="min-w-0 flex-1 space-y-2">
                        <div className="flex flex-wrap items-center gap-2">
                          <h2 className="break-words font-semibold text-gray-950 group-hover:text-primary-700">
                            {policy.name}
                          </h2>
                          <Badge
                            variant={
                              ownership === "facility" ? "primary" : "outline"
                            }
                            size="xs"
                          >
                            {t(`immunization_scope_${ownership}`)}
                          </Badge>
                          {!editable && (
                            <span className="text-xs text-gray-500">
                              {t("read_only")}
                            </span>
                          )}
                        </div>
                        {policy.description && (
                          <p className="line-clamp-2 break-words text-sm leading-5 text-gray-600">
                            {policy.description}
                          </p>
                        )}
                        <p className="text-xs text-gray-500">
                          {t("immunization_policy_recommendation_count", {
                            count: countRecommendations(policy.policy_template),
                          })}
                        </p>
                      </div>
                      <ArrowRight
                        className="size-4 shrink-0 text-gray-400 group-hover:text-primary-700"
                        aria-hidden="true"
                      />
                    </Link>
                  </li>
                );
              })}
            </ul>
          )}
          {!loading && !isError && <Pagination totalCount={data?.count ?? 0} />}
        </>
      )}
    </div>
  );
}

