              })}
            </div>
            <p className="text-xs leading-5 text-gray-500" id={`${id}-offset-help`}>{t("immunization_timing_hint")}</p>
          </section>

          <details key={selectedPath.join(".")} open={!!(node.series || node.dose_number || node.series_number || node.description)} className="group/details border-t border-gray-100 pt-4">
            <summary className="flex cursor-pointer list-none items-center gap-2 text-sm font-medium text-gray-700"><ChevronDown className="size-4 transition-transform group-open/details:rotate-180" aria-hidden="true" />{t("immunization_additional_details")}<span className="ml-auto text-xs font-normal text-gray-400">{t("optional")}</span></summary>
            <div className="space-y-4 pt-4">
              <div className="grid gap-3 sm:grid-cols-3">{TEXT_FIELDS.map(([field, label]) => <div key={field} className="min-w-0 space-y-1.5"><Label htmlFor={`${id}-${field}`}>{t(label)}</Label><Input id={`${id}-${field}`} value={node[field] ?? ""} onChange={(event) => changeNode({ ...node, [field]: event.target.value })} /></div>)}</div>
