import { useQuery } from "@tanstack/react-query";
import { t } from "i18next";

import { callApi } from "@/Utils/request/query";
import { PaginatedResponse } from "@/Utils/request/types";
import {
  ImmunizationPolicyRead,
  ImmunizationPolicyScope,
} from "@/types/emr/immunizationPolicy/immunizationPolicy";
import immunizationPolicyApi from "@/types/emr/immunizationPolicy/immunizationPolicyApi";

interface ImmunizationPolicyOwnership {
  ownership: "instance" | "facility" | "unknown";
  isLoading: boolean;
  isError: boolean;
  refetch: () => Promise<void>;
  /** Scope ownership only; callers must also check write permission. */
  canEditHere: boolean;
}

export async function fetchImmunizationPolicyCatalogue(
  signal: AbortSignal,
  facilityId?: string,
): Promise<PaginatedResponse<ImmunizationPolicyRead>> {
  const policies: ImmunizationPolicyRead[] = [];
  const ids = new Set<string>();
  let expectedCount: number | undefined;
  let offset = 0;

  while (true) {
    const page = await callApi(immunizationPolicyApi.list, {
      signal,
      queryParams: {
        limit: 100,
        offset,
        ...(facilityId ? { facility: facilityId } : {}),
      },
    });

    // Ownership must never be inferred from a truncated or shifting list.
    if (
      !Number.isSafeInteger(page.count) ||
      page.count < 0 ||
      !Array.isArray(page.results) ||
      (expectedCount !== undefined && page.count !== expectedCount)
    ) {
      throw new Error(t("immunization_policy_unknown_scope"));
    }
    expectedCount = page.count;

    for (const policy of page.results) {
      if (!policy.id || ids.has(policy.id)) {
        throw new Error(t("immunization_policy_unknown_scope"));
      }
      ids.add(policy.id);
      policies.push(policy);
    }
    if (ids.size === expectedCount) {
      return { count: expectedCount, results: policies };
    }
    if (ids.size > expectedCount || page.results.length === 0) {
      throw new Error(t("immunization_policy_unknown_scope"));
    }
    offset += page.results.length;
  }
}

export function useImmunizationPolicyOwnership(
  scope: ImmunizationPolicyScope,
  policy?: ImmunizationPolicyRead,
): ImmunizationPolicyOwnership {
  const needsLookup = !!policy && policy.facility === undefined;
  const instancePolicies = useQuery({
    queryKey: ["immunization-policies", "instance-catalogue"],
    queryFn: ({ signal }) => fetchImmunizationPolicyCatalogue(signal),
    enabled: needsLookup,
  });
  const isKnownInstance =
    instancePolicies.isSuccess &&
    !!policy &&
    instancePolicies.data.results.some((entry) => entry.id === policy.id);
  const needsFacilityLookup =
    needsLookup &&
    !!scope.facilityId &&
    instancePolicies.isSuccess &&
    !isKnownInstance;
  const facilityPolicies = useQuery({
    queryKey: ["immunization-policies", "facility-catalogue", scope.facilityId],
    queryFn: ({ signal }) =>
      fetchImmunizationPolicyCatalogue(signal, scope.facilityId),
    enabled: needsFacilityLookup,
  });

  let ownership: ImmunizationPolicyOwnership["ownership"] = "unknown";
  if (policy?.facility === null) {
    ownership = "instance";
  } else if (
    policy?.facility !== undefined &&
    policy.facility === scope.facilityId
  ) {
    ownership = "facility";
  } else if (needsLookup) {
    if (isKnownInstance) ownership = "instance";
    else if (
      needsFacilityLookup &&
      facilityPolicies.isSuccess &&
      facilityPolicies.data.results.some((entry) => entry.id === policy.id)
    ) {
      ownership = "facility";
    }
  }

  return {
    ownership,
    canEditHere: ownership === (scope.facilityId ? "facility" : "instance"),
    isLoading:
      (needsLookup && instancePolicies.isPending) ||
      (needsFacilityLookup && facilityPolicies.isPending),
    isError:
      (needsLookup && instancePolicies.isError) ||
      (needsFacilityLookup && facilityPolicies.isError),
    refetch: async () => {
      if (!needsLookup || !policy) return;
      const instances = await instancePolicies.refetch();
      if (
        instances.isSuccess &&
        !instances.data.results.some((entry) => entry.id === policy.id) &&
        scope.facilityId
      ) {
        await facilityPolicies.refetch();
      }
    },
  };
}
  canEdit,
}: ImmunizationPolicyEditorProps) {
  const { t } = useTranslation();
  const queryClient = useQueryClient();
  const schema = useMemo(() => policySchema(t), [t]);
  type FormValues = z.infer<typeof schema>;
  const form = useForm<FormValues>({
    resolver: zodResolver(schema),
    defaultValues: {
      name: existing?.name ?? "",
      description: existing?.description ?? "",
      policy_template: existing
        ? normalizePolicyTemplate(existing.policy_template)
        : newPolicyTemplate(),
    },
  });
  const template = useWatch({ control: form.control, name: "policy_template" });
  const validation =
    form.formState.submitCount > 0
      ? schema.safeParse(form.getValues())
      : undefined;
  const issues =
    validation && !validation.success ? validation.error.issues : [];
  const isDirty = form.formState.isDirty;
  useNavigationPrompt(canEdit && isDirty, t("unsaved_changes_warning"));

  const handleSaved = () => {
    queryClient.invalidateQueries({ queryKey: ["immunization-policies"] });
    toast.success(
      t(
        existing
          ? "immunization_policy_updated"
          : "immunization_policy_created",
      ),
    );
    flushSync(() => form.reset(form.getValues()));
    navigate(scope.basePath);
  };

  const create = useMutation({
    mutationFn: mutate(immunizationPolicyApi.create),
    onSuccess: handleSaved,
  });
  const update = useMutation({
    mutationFn: mutate(immunizationPolicyApi.update, {
      pathParams: { id: existing?.id ?? "" },
    }),
    onSuccess: handleSaved,
  });
  const isPending = create.isPending || update.isPending;
  const disabled = !canEdit || isPending;
  const title = existing?.name ?? t("immunization_policy_new");
  const shared = !!scope.facilityId && existing?.facility === null;
  const unknownScope = !!existing && existing.facility === undefined;

  return (
    <Page title={title} hideTitleOnPage>
      <Form {...form}>
        <form
          noValidate
          className="mx-auto max-w-5xl space-y-6 pb-6"
          onSubmit={form.handleSubmit((values) => {
            if (!canEdit || isPending) return;
            if (existing) update.mutate(values);
            else
              create.mutate({ ...values, facility: scope.facilityId ?? null });
          })}
        >
          <div className="flex flex-wrap items-center gap-3">
            <Button variant="outline" size="sm" asChild>
              <Link href={scope.basePath} basePath="/">
                <ArrowLeft className="size-4" />
                {t("back")}
              </Link>
            </Button>
            <div className="min-w-0 flex-1">
              <h1 className="break-words text-xl font-bold text-gray-900">
                {title}
              </h1>
              <p className="text-sm text-gray-500">
                {t(
                  scope.facilityId
                    ? "immunization_policy_facility_form_hint"
                    : "immunization_policy_instance_form_hint",
                )}
              </p>
            </div>
            <Badge variant="secondary">
              {t(
                unknownScope
                  ? "immunization_scope_unknown"
                  : shared || !scope.facilityId
                    ? "immunization_scope_instance"
                    : "immunization_scope_facility",
              )}
            </Badge>
            {canEdit && (
              <Button
                type="submit"
                disabled={isPending || (!!existing && !isDirty)}
              >
                {isPending && (
                  <Loader2 className="size-4 animate-spin" aria-hidden="true" />
                )}
                {t("immunization_policy_save")}
              </Button>
            )}
          </div>

          {!canEdit && (
            <Alert>
              <AlertTitle>{t("read_only")}</AlertTitle>
              <AlertDescription>
                {t(
                  unknownScope
                    ? "immunization_policy_unknown_scope"
                    : shared
                      ? "immunization_policy_shared_read_only"
                      : "immunization_policy_read_only",
                )}
              </AlertDescription>
            </Alert>
          )}
          {(create.isError || update.isError) && (
            <Alert variant="destructive">
              <AlertTitle>{t("error")}</AlertTitle>
              <AlertDescription>
                {t("immunization_policy_save_error")}
              </AlertDescription>
            </Alert>
          )}
          {issues.length > 0 && (
            <Alert variant="destructive" role="alert">
              <AlertTitle>
                {t("immunization_policy_validation_title")}
              </AlertTitle>
              <AlertDescription>
                {t("immunization_policy_validation_hint")}
              </AlertDescription>
            </Alert>
          )}

          <fieldset
            disabled={disabled}
            className="space-y-4 rounded-lg border border-gray-200 bg-white p-4 sm:p-5"
          >
            <legend className="px-1 font-semibold text-gray-900">
              {t("basic_information")}
            </legend>
            <FormField
              control={form.control}
              name="name"
              render={({ field }) => (
                <FormItem>
                  <FormLabel aria-required>
                    {t("immunization_policy_name")}
                  </FormLabel>
                  <FormControl>
                    <Input {...field} maxLength={255} />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />
            <FormField
              control={form.control}
              name="description"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>{t("description")}</FormLabel>
                  <FormControl>
                    <Textarea {...field} rows={2} />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />
          </fieldset>

          <PolicyTemplateEditor
            value={template}
            title={t("immunization_recommendation_template")}
            disabled={disabled}
            issues={issues}
            onChange={(value) =>
              form.setValue("policy_template", value, {
                shouldDirty: true,
                shouldValidate: form.formState.submitCount > 0,
              })
            }
          />
        </form>
      </Form>
    </Page>
  );
}

