import { Link } from "raviger";
import { Fragment } from "react";

import { cn } from "@/lib/utils";

import {
  Breadcrumb,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbSeparator,
} from "@/components/ui/breadcrumb";
import { AppSidebarToggle } from "@/components/ui/sidebar/sidebar-toggle";

interface InnerPageBreadcrumb {
  label: string;
  href?: string;
  hideOnMobile?: boolean;
}

interface InnerPageHeaderProps {
  breadcrumbs: InnerPageBreadcrumb[];
  dataCy: string;
}

export function InnerPageHeader({ breadcrumbs, dataCy }: InnerPageHeaderProps) {
  return (
    <header
      data-cy={dataCy}
      className="sticky top-0 z-10 flex h-12 shrink-0 items-center gap-3 border-b border-neutral-200 bg-white px-4 text-neutral-950"
    >
      <AppSidebarToggle />
      <span aria-hidden="true" className="h-5 w-px bg-neutral-200" />
      <Breadcrumb className="min-w-0">
        <BreadcrumbList className="flex-nowrap text-neutral-600">
          {breadcrumbs.map((item, index) => (
            <Fragment key={item.href ?? item.label}>
              <BreadcrumbItem
                className={cn("min-w-0", item.hideOnMobile && "hidden sm:flex")}
              >
                {item.href ? (
                  <BreadcrumbLink asChild>
                    <Link
                      basePath="/"
                      href={item.href}
                      className="truncate rounded-sm underline underline-offset-4 hover:text-neutral-950 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-indigo-500"
                    >
                      {item.label}
                    </Link>
                  </BreadcrumbLink>
                ) : (
                  <BreadcrumbPage className="truncate text-neutral-950">
                    {item.label}
                  </BreadcrumbPage>
                )}
              </BreadcrumbItem>
              {index < breadcrumbs.length - 1 && (
                <BreadcrumbSeparator
                  className={cn(item.hideOnMobile && "hidden sm:block")}
                />
              )}
            </Fragment>
          ))}
        </BreadcrumbList>
      </Breadcrumb>
    </header>
  );
}
  };

  return (
    <>
      <Button
        type="button"
        variant="ghost"
        onClick={() => setScanDialogOpen(true)}
        disabled={isPending}
        aria-label={t("scan_qr")}
        className="h-8 shrink-0 gap-1.5 px-2 text-sm font-medium text-gray-700"
      >
        <ScanLine className="size-4" aria-hidden="true" />
        {t("scan")}
      </Button>
      <PatientIDScanDialog
        open={scanDialogOpen}
        onOpenChange={setScanDialogOpen}
        onScanSuccess={handleScanSuccess}
      />
    </>
  );
};

export const AppointmentEncounterHeader = ({
  appointment,
  encounter,
  canWritePrimaryEncounter,
}: {
  appointment: AppointmentRead;
  encounter: EncounterRead;
  canWritePrimaryEncounter: boolean;
}) => {
  const { t } = useTranslation();
  return (
    <div className="flex min-w-0 flex-1 flex-wrap items-center gap-x-3 gap-y-1 py-1">
      <div
        role="group"
        aria-label={t("appointment")}
        className="flex min-w-0 flex-wrap items-center gap-0.5"
      >
        <PatientScanButton
          facilityId={encounter.facility.id}
          appointment={appointment}
        />
        <TokenActions
          patientId={encounter.patient.id}
          facilityId={encounter.facility.id}
          appointment={appointment}
          resourceType={appointment.resource_type}
          resourceId={appointment.resource.id}
        />
      </div>
      {canWritePrimaryEncounter && (
        <div className="ml-auto flex min-w-0 items-center">
          <AppointmentEncounterHeaderActions encounter={encounter} />
        </div>
      )}
    </div>
  );
};

const AppointmentEncounterHeaderActions = ({
  encounter,
}: {
  encounter: EncounterRead;
}) => {
  const { t } = useTranslation();
  const queryClient = useQueryClient();
  const requiresDischarge = encounterRequiresDischarge(encounter);

  const { completeEverything, completeAppointment, isPending } =
    useEncounterProgressController({
      encounter,
    });

  const { mutate: startEncounter } = useMutation({
    mutationFn: mutate(encounterApi.update, {
      pathParams: { id: encounter.id },
    }),
    onSuccess: () => {
      queryClient.invalidateQueries({
        queryKey: ["encounter", encounter.id],
      });
    },
  });

  const handleStartEncounter = () => {
    startEncounter({
      ...encounter,
      status: EncounterStatus.IN_PROGRESS,
    });
  };

  if (
    encounter.status === EncounterStatus.PLANNED ||
    encounter.status === EncounterStatus.ON_HOLD
  ) {
    return (
      <div
        role="group"
        aria-label={t("encounter_actions")}
        className="flex min-w-0 flex-wrap items-center gap-1"
      >
        <Button
          type="button"
          variant="outline"
          className="h-auto min-h-8 max-w-full whitespace-normal border-gray-300 px-3 py-1.5 text-sm shadow-none"
          onClick={handleStartEncounter}
        >
          {t("start_encounter")}
        </Button>
      </div>
    );
  }

  return (
    <div
      role="group"
      aria-label={t("encounter_actions")}
      className="flex min-w-0 flex-wrap items-center gap-1"
    >
      <Button
        type="button"
        variant="outline"
        className="h-auto min-h-8 max-w-full gap-1.5 whitespace-normal border-gray-300 px-3 py-1.5 text-sm shadow-none"
        disabled={isPending}
        onClick={completeEverything}
      >
        <CheckCircle aria-hidden="true" />
        {requiresDischarge ? t("mark_for_discharge") : t("complete")}
      </Button>
      {encounter.status !== EncounterStatus.COMPLETED && (
        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <Button
              type="button"
              variant="ghost"
              size="icon"
              className="size-8 shrink-0"
              aria-label={t("more_actions")}
            >
              <DotsVerticalIcon className="text-gray-700" aria-hidden="true" />
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent className="max-w-[calc(100vw-2rem)]" align="end">
            {encounter.appointment?.status !== AppointmentStatus.FULFILLED && (
              <DropdownMenuItem
                className="p-2.5"
                onClick={() => completeAppointment()}
                disabled={isPending}
              >
                <div className="flex flex-col items-start">
                  <span className="text-sm font-medium text-black">
                    {t("close_appointment")}
                  </span>
                  <p className="text-xs text-gray-700">
                    {t("close_appointment_description")}
                  </p>
                </div>
              </DropdownMenuItem>
            )}
            <DropdownMenuItem
              className="p-2.5"
              onClick={() => completeEverything()}
              disabled={isPending}
            >
              <div className="flex flex-col items-start">
                <span className="text-sm font-medium text-black">
                  {requiresDischarge
                    ? t("mark_for_discharge")
                    : t("mark_as_complete")}
                </span>
                <p className="text-xs text-gray-700">
                  {requiresDischarge
                    ? t("mark_for_discharge_description")
                    : t("mark_as_complete_description")}
                </p>
              </div>
            </DropdownMenuItem>
          </DropdownMenuContent>
        </DropdownMenu>
      )}
    </div>
  );
};

const TokenActions = ({
  patientId,
  facilityId,
  appointment,
  resourceType,
  resourceId,
}: {
  patientId: string;
  facilityId: string;
  appointment?: AppointmentRead;
  resourceType: SchedulableResourceType;
  resourceId: string;
}) => {
  const { t } = useTranslation();
  const { responsibilityId } = useRouteParams(
    "/responsibilities/:responsibilityId",
  );
  const facility = user?.facilities.find((item) => item.id === facilityId);
  const organization = user?.organizations.find(
    (item) => item.id === organizationId,
  );

  return (
    <header
      data-cui-app-header
      className={cn(
        "sticky top-0 z-10 flex shrink-0 items-center gap-3 border-b border-neutral-200 bg-white px-4 text-neutral-950",
        innerWorkspace
          ? "min-h-12 py-1.5"
          : "min-h-14 py-2 md:rounded-t-[14px]",
      )}
    >
      <AppSidebarToggle />
      <div
        ref={setTarget}
        className={cn("min-w-0 flex-1", !hasContent && "hidden")}
      />
      {!hasContent &&
        (children ?? (
          <>
            <span
              aria-hidden="true"
              className="h-5 w-px shrink-0 bg-neutral-200"
            />
            <div className="min-w-0 max-w-[min(20rem,65vw)]">
              {patient ? (
                <PatientSwitcher />
              ) : responsibilityId ? (
                <ResponsibilitySwitcher
                  selectedResponsibilityId={responsibilityId}
                />
              ) : organization ? (
                <OrganizationSwitcher
                  organizations={user?.organizations ?? []}
                  selectedOrganization={organization}
                />
              ) : facility ? (
                <FacilitySwitcher
                  facilities={user?.facilities ?? []}
                  selectedFacility={facility}
                />
              ) : (
                <span className="truncate text-sm font-medium">
                  {t("care")}
                </span>
              )}
            </div>
          </>
        ))}
      {onSearch && (
        <Button
          variant="outline"
          size="sm"
          onClick={onSearch}
          aria-label={t("search_page_actions")}
          className={cn(
            "ml-auto size-8 shrink-0 gap-2 rounded-lg border-neutral-300 bg-white p-0 text-neutral-500 shadow-sm hover:bg-neutral-100 focus-visible:ring-indigo-400",
            hasCustomContent
              ? "2xl:h-9 2xl:w-52 2xl:justify-start 2xl:px-3"
              : "sm:h-9 sm:w-52 sm:justify-start sm:px-3",
          )}
        >
          <Search className="size-4" aria-hidden="true" />
          <span
            className={
              hasCustomContent ? "hidden 2xl:inline" : "hidden sm:inline"
            }
          >
            {t("search_page_actions")}
          </span>
        </Button>
      )}
    </header>
  );
}

