                  : t("not_specified")}
              </MetaPair>
              <MetaPair label={t("end_date")}>
                {encounter.period.end
                  ? formatDateTime(encounter.period.end)
                  : t("ongoing")}
              </MetaPair>
              {encounter.external_identifier && (
