export function FillPageBody({
  questionnaire,
  patient,
  encounter,
  subject,
  pickerSubjectType,
  scope,
  localDraft,
  resumeLocalDraft = false,
  serverDraftResponses,
  serverDraftDropped,
  continueDraftId,
  serverDraft,
  exitTarget,
