  onRetryContext,
}: FillPageBodyProps) {
  const { t } = useTranslation();
  const queryClient = useQueryClient();
  const [showCloseConfirmation, setShowCloseConfirmation] = useState(false);
  const storesRef = useRef(new Map<string, FormStore>());
