    scope,
    persistLocally: !continueDraftId,
    forms,
    getStore,
    storesVersion,
    restoredDraft: localDraft,
    resumeAutomatically: resumeLocalDraft,
    retainedSnapshots,
    onResumeAddedForms,
  });

