export interface QuestionnaireFormRendererProps extends CanvasSlots {
  questionnaire: QuestionnaireRead;
  mode: FormMode;
  subject?: RendererSubject;
  /** Builder edit canvas: render enable_when-hidden questions too. */
  revealHidden?: boolean;
  /** Builder edit canvas: inputs visible but non-interactive. */
  inert?: boolean;
  /** Creation-time seed overrides (a restored draft) — forwarded verbatim
   *  to the provider, which applies them once. See FormContext. */
  initialResponses?: Record<string, QuestionnaireResponse>;
  /** Decoration seam — see chrome.tsx. */
  chrome?: FormChrome;
}

/**
 * The renderer: the whole questionnaire on one scroll — top-level groups
 * as section cards, everything live against the per-instance store. The
 * studio canvas, the read-only previews and the fill flow all mount this
 * one module; there is no second renderer.
 */
export function QuestionnaireFormRenderer({
  questionnaire,
  mode,
  subject,
  revealHidden,
  inert,
  initialResponses,
  chrome = EMPTY_CHROME,
  emptyState,
  hideHeader,
  headerHint,
  className,
}: QuestionnaireFormRendererProps) {
  return (
    <QuestionnaireFormProvider
      questionnaire={questionnaire}
      mode={mode}
      subject={subject}
      revealHidden={revealHidden}
      inert={inert}
      initialResponses={initialResponses}
    >
      <FormChromeProvider chrome={chrome}>
        <CanvasBody
          emptyState={emptyState}
          hideHeader={hideHeader}
          headerHint={headerHint}
          className={className}
        />
      </FormChromeProvider>
    </QuestionnaireFormProvider>
  );
}

/**
 * The canvas body for hosts that mount `QuestionnaireFormProvider`
 * themselves — the studio does, so its outline and canvas share one store
 * (the outline's preview mode reads live enable_when hidden ids).
 */
export function QuestionnaireFormCanvas({
  chrome = EMPTY_CHROME,
  emptyState,
  hideHeader,
  headerHint,
  className,
}: CanvasSlots & { chrome?: FormChrome }) {
  return (
    <FormChromeProvider chrome={chrome}>
      <CanvasBody
        emptyState={emptyState}
        hideHeader={hideHeader}
        headerHint={headerHint}
        className={className}
      />
    </FormChromeProvider>
  );
}

function CanvasBody({
  emptyState,
  hideHeader,
  headerHint,
  className,
}: CanvasSlots) {
  const { t } = useTranslation();
  const { questionnaire, revealHidden } = useFormRenderer();
  const { AppendZone } = useFormChrome();
  const hasVisibleQuestions = useHasVisibleTopLevelQuestions();
  const questions = questionnaire.questions;

  const sectionCount = questions.filter(
    (question) => question.type === "group",
  ).length;
  const countLine = [
    sectionCount > 0 && t("n_sections", { count: sectionCount }),
    t("n_questions", { count: countLeafQuestions(questions) }),
  ]
    .filter(Boolean)
    .join(" · ");

  const header = !hideHeader && (
    <div className="flex items-baseline justify-between gap-3 pb-4">
      <div className="min-w-0 space-y-1">
        <h2 className="text-lg font-semibold tracking-tight text-gray-900">
          {questionnaire.title}
        </h2>
        {questionnaire.description && (
          <p className="text-sm text-gray-500">{questionnaire.description}</p>
        )}
        {questions.length > 0 && (
          <p className="text-xs text-gray-400">{countLine}</p>
        )}
      </div>
      {headerHint && (
        <div className="shrink-0 text-xs text-gray-400">{headerHint}</div>
      )}
    </div>
  );

  if (questions.length === 0) {
    return (
      <div className={cn("mx-auto w-full max-w-3xl", className)}>
        {header}
        {emptyState ?? (
          <div className="rounded-lg bg-white p-8 text-center text-sm text-gray-500">
            {t("no_questions_added_yet")}
          </div>
        )}
      </div>
    );
  }

  // Every top-level question hidden by enable_when: explain the empty form
  // instead of a blank canvas. The edit canvas (`revealHidden`) never hits
  // this — hidden questions render there with a logic badge.
  if (!revealHidden && !hasVisibleQuestions) {
    return (
      <div className={cn("mx-auto w-full max-w-3xl", className)}>
        {header}
        <div className="p-8 text-center text-sm text-gray-500">
          {t("no_visible_questions")}
        </div>
      </div>
    );
  }

  return (
    <div className={cn("mx-auto w-full max-w-3xl", className)}>
      {header}
      <div className="space-y-4 pb-4">
        {questions.map((question, index) => (
          <QuestionBlock
            key={question.id}
            question={question}
            parentId={null}
            index={index}
            siblingCount={questions.length}
            depth={0}
            number={`${index + 1}.`}
          />
        ))}
        {AppendZone && <AppendZone parentId={null} />}
      </div>
    </div>
  );
}
import { Trash2 } from "lucide-react";
import { createPortal } from "react-dom";
import { useTranslation } from "react-i18next";

import { cn } from "@/lib/utils";

import { Button } from "@/components/ui/button";

import { QuestionnaireFormProvider } from "@/components/QuestionnaireV2/form/FormContext";

import type { RendererSubject } from "@/components/QuestionnaireV2/form/types";

import { FillCanvas } from "./FillCanvas";
import { FillOutline } from "./FillOutline";
import { FillOutlineRail } from "./FillOutlineRail";
import type { FormStore } from "./StoreRegistrar";
import { StoreRegistrar } from "./StoreRegistrar";
import type { FillFormEntry } from "./formSession";

/**
 * One questionnaire of the session: its own provider (one store), its
 * canvas block in the shared scroll, and its outline pieces PORTALED
 * into the overlay's shared hosts (panel rows + rail ticks) — they must
 * live inside this provider to read this form's store.
 */
export function FillFormSection({
  form,
  subject,
  outlineHost,
  railHost,
  outlineLabel,
  onStore,
  onRemove,
  frozen = false,
}: {
  form: FillFormEntry;
  subject: RendererSubject;
  outlineHost: HTMLElement | null;
  railHost: HTMLElement | null;
  /** Accessible name for this form's outline landmark. The host passes
   *  the questionnaire title once a session holds more than one form, so
   *  the stacked navs stay distinguishable. */
  outlineLabel?: string;
  onStore: (key: string, store: FormStore | null) => void;
  onRemove?: (key: string) => void;
  /** The session is mid-submit — forwarded into this form's renderer
   *  context (freezes every question) and disables the Remove affordance
   *  below, so a click during flight can't drop a form the in-flight
   *  batch already accounts for. */
  frozen?: boolean;
}) {
  const { t } = useTranslation();
  return (
    <QuestionnaireFormProvider
      questionnaire={form.questionnaire}
      mode="fill"
      subject={subject}
      initialResponses={form.initialResponses}
      frozen={frozen}
    >
      <StoreRegistrar formKey={form.key} onStore={onStore} />
      {outlineHost &&
        createPortal(
          <div className="flex flex-col gap-3">
            <p className="truncate pl-2 text-base font-semibold text-gray-950">
              {form.questionnaire.title}
            </p>
            <FillOutline ariaLabel={outlineLabel} />
          </div>,
          outlineHost,
        )}
      {railHost && createPortal(<FillOutlineRail />, railHost)}
      {/* The divider keys off `isPrimary`, not `:first-child` — the
          restore bar and the error panel share this scroll, so DOM
          position is not a reliable "first form" signal. */}
      <section
        data-form-key={form.key}
        className={cn(!form.isPrimary && "border-t border-gray-200 pt-6")}
      >
        {/* Only added forms get a remove affordance; the canvas header already
            names the questionnaire. */}
        {onRemove && !form.isPrimary && (
          <div className="mx-auto mb-2 flex w-full max-w-3xl justify-end">
            <Button
              type="button"
              variant="ghost"
              size="sm"
              // The button sits ABOVE its own form's header, so in reading
              // order it follows the PREVIOUS form's last question — a
              // session with two added forms would otherwise expose two
              // buttons both named just "Remove", and activating the wrong
              // one drops that questionnaire and its answers from the
              // session and from the persisted draft.
              aria-label={t("remove_questionnaire", {
                title: form.questionnaire.title,
              })}
              disabled={frozen}
              onClick={() => onRemove(form.key)}
            >
              <Trash2 className="size-4" />
              {t("remove")}
            </Button>
          </div>
        )}
        <FillCanvas />
      </section>
    </QuestionnaireFormProvider>
  );
}
