  encounter,
  subject,
  pickerSubjectType,
  scope,
  localDraft,
  resumeLocalDraft = false,
  serverDraftResponses,
  serverDraftDropped,
  continueDraftId,
  serverDraft,
  exitTarget,
  contextRefreshFailed,
  isRetryingContext,
  onRetryContext,
