  const serverDraftSave = useSaveServerDraft({
    forms,
    getStore,
    subject,
    continueDraftId,
    onSaved: () => {
      autosave.finishDraft();
      navigate(exitTarget);
    },
  });

  const discardServerDraft = useMutation({
    mutationFn: async (draft: FormSubmissionRead) => {
