    <FillSessionTabs
      patientId={patientId}
      facilityId={facilityId}
      dirty={autosave.dirty}
      onClose={requestClose}
      onMinimize={minimizeSession}
      exitDisabled={frozen}
      minimizeDisabled={
        !!continueDraftId &&
        (!serverDraftSave.canSaveDraft || contextRefreshFailed)
