    if (host.closest(OPEN_OVERLAY_SELECTOR)) {
      lastInOverlay = host;
    }
  }

  if (lastInOverlay) {
    return lastInOverlay;
  }

  if (document.querySelector(MOUNTED_OVERLAY_SELECTOR)) {
    return undefined;
  }

  return hosts[0];
}

